-- Upgrade for an existing install: switch the main quiz to the workbook questions.
-- 1. Adds the "her view" wording column.
-- 2. DELETES all existing MAIN categories and questions, and every answer to them.
--    Intro questions and their answers are kept. Back up first (phpMyAdmin > Export).
-- New installs do not need this: install.sql already includes it.

SET NAMES utf8mb4;

ALTER TABLE questions ADD COLUMN text_female VARCHAR(1000) NULL AFTER text;

DELETE FROM categories WHERE section = 'main';

